-- Azumofuyuki Chat: run this entire file once in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null check(username ~ '^[A-Za-z0-9_]{3,16}$'),username_key text not null unique,role text not null default 'member' check(role in('member','moderator','admin')),status text not null default 'pending' check(status in('pending','approved','banned','rejected')),verification_code text,verification_expires_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.channels(id uuid primary key default gen_random_uuid(),name text not null unique check(name ~ '^[a-z0-9_-]{1,24}$'),description text not null default '',is_private boolean not null default false,archived boolean not null default false,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),channel_id uuid not null references public.channels(id) on delete cascade,user_id uuid not null references public.profiles(id),body text not null check(char_length(body) between 1 and 2000),reply_to uuid references public.messages(id) on delete set null,edited_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now());
create index if not exists messages_channel_created_idx on public.messages(channel_id,created_at desc);
create table if not exists public.reactions(id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,emoji text not null check(emoji in('👍','❤️','😂','🎉','👀','🔥','😮','😢')),created_at timestamptz not null default now(),unique(message_id,user_id,emoji));
create table if not exists public.pins(message_id uuid primary key references public.messages(id) on delete cascade,channel_id uuid not null references public.channels(id) on delete cascade,pinned_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.dm_conversations(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now());
create table if not exists public.dm_participants(conversation_id uuid not null references public.dm_conversations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,primary key(conversation_id,user_id));
create table if not exists public.dm_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.dm_conversations(id) on delete cascade,user_id uuid not null references public.profiles(id),body text not null check(char_length(body) between 1 and 2000),created_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,kind text not null,body text not null,is_read boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.attachments(id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,owner_id uuid not null references public.profiles(id),storage_path text not null unique,file_name text not null,mime_type text not null,size bigint not null check(size between 1 and 15728640),created_at timestamptz not null default now());
create table if not exists public.channel_permissions(channel_id uuid primary key references public.channels(id) on delete cascade,members_can_send boolean not null default true);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin' and status='approved') $$;
create or replace function public.is_approved() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and status='approved') $$;
create or replace function public.can_access_channel(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.channels c where c.id=cid and c.archived=false and (not c.is_private or public.is_admin())) $$;
create or replace function public.can_access_message(mid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.messages m where m.id=mid and public.can_access_channel(m.channel_id)) $$;
create or replace function public.is_dm_participant(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.dm_participants where conversation_id=cid and user_id=auth.uid()) $$;
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public,auth as $$ declare n text; begin n:=new.raw_user_meta_data->>'username'; if n is null or n !~ '^[A-Za-z0-9_]{3,16}$' then raise exception 'Invalid Minecraft username'; end if; insert into public.profiles(id,username,username_key) values(new.id,n,lower(n)); return new; end $$;
drop trigger if exists auth_user_profile on auth.users;
create trigger auth_user_profile after insert on auth.users for each row execute procedure public.new_profile();
create or replace function public.request_verification() returns text language plpgsql security definer set search_path=public as $$ declare c text; begin if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and status='pending') then raise exception '申請できません'; end if; c:=lpad((floor(random()*900000)+100000)::int::text,6,'0'); update public.profiles set verification_code=c,verification_expires_at=now()+interval '30 minutes' where id=auth.uid(); return c; end $$;
create or replace function public.approve_application(p_user_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception '管理者権限が必要です'; end if; update public.profiles set status='approved',verification_code=null,verification_expires_at=null where id=p_user_id and status='pending' and verification_code is not null and verification_expires_at>now(); if not found then raise exception '申請なし、または確認コード期限切れ'; end if; end $$;
create or replace function public.reject_application(p_user_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception '管理者権限が必要です'; end if; update public.profiles set status='rejected',verification_code=null,verification_expires_at=null where id=p_user_id and status='pending'; end $$;
create or replace function public.set_member_status(p_user_id uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() or p_status not in('approved','banned') then raise exception '操作できません'; end if; update public.profiles set status=p_status where id=p_user_id and role<>'admin'; end $$;
create or replace function public.set_member_role(p_user_id uuid,p_role text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() or p_role not in('member','moderator') then raise exception '操作できません'; end if; update public.profiles set role=p_role where id=p_user_id and role<>'admin'; end $$;
create or replace function public.create_channel(p_name text,p_description text default '',p_private boolean default false) returns uuid language plpgsql security definer set search_path=public as $$ declare cid uuid; begin if not public.is_admin() then raise exception '管理者権限が必要です'; end if; insert into public.channels(name,description,is_private,created_by) values(lower(p_name),coalesce(p_description,''),p_private,auth.uid()) returning id into cid; insert into public.channel_permissions(channel_id) values(cid); return cid; end $$;
create or replace function public.create_dm(p_username text) returns uuid language plpgsql security definer set search_path=public as $$ declare target uuid; cid uuid; begin if not public.is_approved() then raise exception '承認済みアカウントが必要です'; end if; select id into target from public.profiles where username_key=lower(p_username) and status='approved'; if target is null or target=auth.uid() then raise exception '相手が見つかりません'; end if; select a.conversation_id into cid from public.dm_participants a join public.dm_participants b on a.conversation_id=b.conversation_id where a.user_id=auth.uid() and b.user_id=target limit 1; if cid is null then insert into public.dm_conversations default values returning id into cid; insert into public.dm_participants values(cid,auth.uid()),(cid,target); end if; return cid; end $$;
create or replace function public.edit_message(p_message_id uuid,p_body text) returns void language plpgsql security definer set search_path=public as $$ declare m public.messages; begin select * into m from public.messages where id=p_message_id; if m.id is null or (m.user_id<>auth.uid() and not public.is_admin() and not exists(select 1 from public.profiles where id=auth.uid() and role='moderator' and status='approved')) then raise exception '編集できません'; end if; if length(trim(p_body))<1 or length(p_body)>2000 then raise exception '本文は1〜2000文字です'; end if; update public.messages set body=trim(p_body),edited_at=now() where id=p_message_id; end $$;
create or replace function public.delete_message(p_message_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare m public.messages; begin select * into m from public.messages where id=p_message_id; if m.id is null or (m.user_id<>auth.uid() and not public.is_admin() and not exists(select 1 from public.profiles where id=auth.uid() and role='moderator' and status='approved')) then raise exception '削除できません'; end if; update public.messages set body='このメッセージは削除されました',deleted_at=now() where id=p_message_id; end $$;
create or replace function public.search_messages(p_query text) returns table(id uuid,channel_id uuid,channel_name text,username text,body text,created_at timestamptz) language sql stable security definer set search_path=public as $$ select m.id,m.channel_id,c.name,p.username,m.body,m.created_at from public.messages m join public.channels c on c.id=m.channel_id join public.profiles p on p.id=m.user_id where public.is_approved() and public.can_access_channel(c.id) and m.deleted_at is null and length(trim(p_query))>=2 and m.body ilike '%'||replace(trim(p_query),'%','\%')||'%' order by m.created_at desc limit 50 $$;
create or replace function public.mention_notify() returns trigger language plpgsql security definer set search_path=public as $$ declare p record; begin for p in select id from public.profiles where status='approved' and id<>new.user_id and lower(new.body) ~ ('@'||username_key||'([^a-z0-9_]|$)') loop insert into public.notifications(user_id,kind,body) values(p.id,'mention','メッセージであなたがメンションされました'); end loop; return new; end $$;
drop trigger if exists message_mentions on public.messages;
create trigger message_mentions after insert on public.messages for each row execute procedure public.mention_notify();
create or replace function public.dm_notify() returns trigger language plpgsql security definer set search_path=public as $$ declare target uuid; sender text; begin select user_id into target from public.dm_participants where conversation_id=new.conversation_id and user_id<>new.user_id limit 1; select username into sender from public.profiles where id=new.user_id; if target is not null then insert into public.notifications(user_id,kind,body) values(target,'dm',sender||' からDMが届きました'); end if; return new; end $$;
drop trigger if exists dm_notification on public.dm_messages;
create trigger dm_notification after insert on public.dm_messages for each row execute procedure public.dm_notify();
alter table public.profiles enable row level security;
alter table public.channels enable row level security;
alter table public.messages enable row level security;
alter table public.reactions enable row level security;
alter table public.pins enable row level security;
alter table public.dm_participants enable row level security;
alter table public.dm_messages enable row level security;
alter table public.notifications enable row level security;
alter table public.attachments enable row level security;
alter table public.channel_permissions enable row level security;
drop policy if exists profiles_read on public.profiles;
create policy profiles_read on public.profiles for select to authenticated using(status='approved' or id=auth.uid() or public.is_admin());
drop policy if exists channels_read on public.channels;
create policy channels_read on public.channels for select to authenticated using(public.is_approved() and not archived and (not is_private or public.is_admin()));
drop policy if exists messages_read on public.messages;
create policy messages_read on public.messages for select to authenticated using(public.is_approved() and public.can_access_channel(channel_id));
drop policy if exists messages_insert on public.messages;
create policy messages_insert on public.messages for insert to authenticated with check(user_id=auth.uid() and public.is_approved() and public.can_access_channel(channel_id) and (public.is_admin() or coalesce((select cp.members_can_send from public.channel_permissions cp where cp.channel_id=messages.channel_id),true)));
drop policy if exists reactions_read on public.reactions;
create policy reactions_read on public.reactions for select to authenticated using(public.can_access_message(message_id));
drop policy if exists reactions_insert on public.reactions;
create policy reactions_insert on public.reactions for insert to authenticated with check(user_id=auth.uid() and public.is_approved() and public.can_access_message(message_id));
drop policy if exists reactions_delete on public.reactions;
create policy reactions_delete on public.reactions for delete to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists pins_read on public.pins;
create policy pins_read on public.pins for select to authenticated using(public.can_access_channel(channel_id));
drop policy if exists pins_admin on public.pins;
create policy pins_admin on public.pins for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists dm_participants_read on public.dm_participants;
create policy dm_participants_read on public.dm_participants for select to authenticated using(public.is_dm_participant(conversation_id));
drop policy if exists dm_messages_read on public.dm_messages;
create policy dm_messages_read on public.dm_messages for select to authenticated using(public.is_approved() and public.is_dm_participant(conversation_id));
drop policy if exists dm_messages_insert on public.dm_messages;
create policy dm_messages_insert on public.dm_messages for insert to authenticated with check(user_id=auth.uid() and public.is_approved() and public.is_dm_participant(conversation_id));
drop policy if exists notifications_read on public.notifications;
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid());
drop policy if exists notifications_update on public.notifications;
create policy notifications_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists attachments_read on public.attachments;
create policy attachments_read on public.attachments for select to authenticated using(owner_id=auth.uid() or public.can_access_message(message_id));
drop policy if exists attachments_insert on public.attachments;
create policy attachments_insert on public.attachments for insert to authenticated with check(owner_id=auth.uid() and public.is_approved() and exists(select 1 from public.messages m where m.id=message_id and m.user_id=auth.uid()));
drop policy if exists attachments_delete on public.attachments;
create policy attachments_delete on public.attachments for delete to authenticated using(owner_id=auth.uid() or public.is_admin());
drop policy if exists channel_permissions_read on public.channel_permissions;
create policy channel_permissions_read on public.channel_permissions for select to authenticated using(public.can_access_channel(channel_id));
insert into public.channels(name,description) values('general','みんなの雑談チャンネル') on conflict(name) do nothing;
insert into public.channel_permissions(channel_id) select id from public.channels on conflict(channel_id) do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('chat-attachments','chat-attachments',false,15728640,array['image/png','image/jpeg','image/gif','image/webp','application/pdf','text/plain','application/zip']) on conflict(id) do update set public=false,file_size_limit=15728640,allowed_mime_types=excluded.allowed_mime_types;
create or replace function public.can_read_chat_file(n text,uid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.attachments a where a.storage_path=n and (a.owner_id=uid or public.can_access_message(a.message_id))) $$;
drop policy if exists chat_files_insert on storage.objects;
create policy chat_files_insert on storage.objects for insert to authenticated with check(bucket_id='chat-attachments' and (storage.foldername(name))[1]=auth.uid()::text and public.is_approved());
drop policy if exists chat_files_read on storage.objects;
create policy chat_files_read on storage.objects for select to authenticated using(bucket_id='chat-attachments' and public.can_read_chat_file(name,auth.uid()));
drop policy if exists chat_files_delete on storage.objects;
create policy chat_files_delete on storage.objects for delete to authenticated using(bucket_id='chat-attachments' and (storage.foldername(name))[1]=auth.uid()::text);
do $$ begin alter publication supabase_realtime add table public.messages; exception when duplicate_object then null; when undefined_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.dm_messages; exception when duplicate_object then null; when undefined_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.attachments; exception when duplicate_object then null; when undefined_object then null; end $$;
